import { cacheTag } from 'next/cache'

export type Post = {
  id: number
  title: string
  createdAt: string
}

// In-memory store standing in for a database. `globalThis` keeps it
// stable across HMR reloads in dev.
const store = (globalThis as { __posts?: Post[] }).__posts ?? []
;(globalThis as { __posts?: Post[] }).__posts = store

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')

  return [...store]
}

export async function insertPost(title: string): Promise<Post> {
  const post: Post = {
    id: store.length + 1,
    title,
    createdAt: new Date().toISOString(),
  }
  store.push(post)
  return post
}

